SELECT toDate(block_time) AS day,finality,capture_mode,quote_coverage,canonical,committed,count() AS blocks,min(block_time) AS first_utc,max(block_time) AS latest_utc,min(block_number) AS first_height,max(block_number) AS last_height FROM dex_block FINAL WHERE chain_id=1 AND manifest_hash=unhex('e5493d29bf16f2d7665e90163eda323e2e7a2847e4bd3e7563db77ac11bfe567') AND block_time>='2026-09-28 00:00:00' GROUP BY day,finality,capture_mode,quote_coverage,canonical,committed ORDER BY day,finality,capture_mode,quote_coverage FORMAT JSONEachRow
